using System.Collections.Concurrent;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Text;
using DevLab.Api.Features.Auth.Jwt;
using DevLab.Api.Features.Auth.Users;
using Microsoft.Extensions.Options;
using Microsoft.IdentityModel.JsonWebTokens;
using Microsoft.IdentityModel.Tokens;

namespace DevLab.Api.Features.Auth.Oidc;

public sealed class IdpOptions
{
    public const string Section = "Idp";
    public string Issuer { get; set; } = "";
    public string ClientId { get; set; } = "";
    public string[] RedirectUris { get; set; } = [];
}

/// <summary>
/// A miniature OpenID Connect provider (think: Google, Entra ID, Keycloak, Auth0) hosted
/// in-process so the Authorization Code + PKCE flow can be watched step by step.
/// It is NOT production-grade — it exists to make the protocol tangible.
/// </summary>
public sealed class FakeIdentityProvider(IOptions<IdpOptions> idp, IOptions<JwtOptions> jwt, InMemoryUserStore users, TimeProvider clock)
{
    private sealed record PendingCode(string UserName, string CodeChallenge, string RedirectUri, string Nonce, DateTimeOffset ExpiresAt);
    private readonly ConcurrentDictionary<string, PendingCode> _codes = new();

    public IdpOptions Options => idp.Value;

    public bool IsValidClient(string clientId, string redirectUri) =>
        clientId == idp.Value.ClientId && idp.Value.RedirectUris.Contains(redirectUri);

    /// <summary>Step 2: user consented → issue a one-time authorization code bound to the PKCE challenge.</summary>
    public string IssueCode(string userName, string codeChallenge, string redirectUri, string nonce)
    {
        var code = Convert.ToBase64String(RandomNumberGenerator.GetBytes(32)).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        _codes[code] = new PendingCode(userName, codeChallenge, redirectUri, nonce, clock.GetUtcNow().AddMinutes(2));
        return code;
    }

    /// <summary>Step 3: exchange code + verifier → tokens. The verifier proves the caller started the flow.</summary>
    public (string? Error, object? Tokens) Exchange(string code, string codeVerifier, string redirectUri)
    {
        if (!_codes.TryRemove(code, out var pending)) return ("invalid_grant: unknown or already used code", null);
        if (pending.ExpiresAt < clock.GetUtcNow()) return ("invalid_grant: code expired", null);
        if (pending.RedirectUri != redirectUri) return ("invalid_grant: redirect_uri mismatch", null);

        // PKCE: SHA256(code_verifier) must equal the code_challenge sent at /authorize.
        var expected = Base64Url(SHA256.HashData(Encoding.ASCII.GetBytes(codeVerifier)));
        if (!CryptographicOperations.FixedTimeEquals(Encoding.ASCII.GetBytes(expected), Encoding.ASCII.GetBytes(pending.CodeChallenge)))
            return ("invalid_grant: PKCE verification failed", null);

        var user = users.FindByName(pending.UserName)!;
        var now = clock.GetUtcNow();
        var expires = now.AddMinutes(10);

        var claims = new List<Claim>
        {
            new("sub", user.Id), new("name", user.UserName), new("preferred_username", user.UserName),
            new("email", $"{user.UserName}@devlab.local"), new("nonce", pending.Nonce),
        };
        claims.AddRange(user.Roles.Select(r => new Claim("role", r)));

        var handler = new JsonWebTokenHandler();
        var idToken = handler.CreateToken(new SecurityTokenDescriptor
        {
            Issuer = idp.Value.Issuer,
            Audience = idp.Value.ClientId,
            Subject = new ClaimsIdentity(claims),
            IssuedAt = now.UtcDateTime, Expires = expires.UtcDateTime,
            SigningCredentials = new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwt.Value.SigningKey)), SecurityAlgorithms.HmacSha256),
        });

        return (null, new
        {
            access_token = idToken, // simplified: same token doubles as access token for our API
            id_token = idToken,
            token_type = "Bearer",
            expires_in = (int)(expires - now).TotalSeconds,
            scope = "openid profile email",
        });
    }

    public object? UserInfo(string userName) =>
        users.FindByName(userName) is { } u ? new { sub = u.Id, name = u.UserName, email = $"{u.UserName}@devlab.local", roles = u.Roles } : null;

    private static string Base64Url(byte[] bytes) => Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
}

using System.Security.Claims;
using DevLab.Api.Features.Auth.Jwt;
using DevLab.Api.Features.Auth.Users;

namespace DevLab.Api.Features.Auth.Oidc;

public static class FakeIdentityProviderEndpoints
{
    public static IServiceCollection AddFakeIdentityProvider(this IServiceCollection services, IConfiguration config) =>
        services.AddSingleton<FakeIdentityProvider>();

    public static IEndpointRouteBuilder MapFakeIdentityProviderEndpoints(this IEndpointRouteBuilder app)
    {
        var idp = app.MapGroup("/idp").WithTags("Auth · Fake IdP (OIDC)");

        // Discovery document: clients read this to find the endpoints (real IdPs also publish jwks_uri).
        idp.MapGet("/.well-known/openid-configuration", (FakeIdentityProvider p, HttpRequest req) => TypedResults.Ok(new
        {
            issuer = p.Options.Issuer,
            authorization_endpoint = $"{req.Scheme}://{req.Host}/idp/authorize",
            token_endpoint = $"{req.Scheme}://{req.Host}/idp/token",
            userinfo_endpoint = $"{req.Scheme}://{req.Host}/idp/userinfo",
            response_types_supported = new[] { "code" },
            code_challenge_methods_supported = new[] { "S256" },
            scopes_supported = new[] { "openid", "profile", "email" },
        }));

        // Step 1 — the browser is REDIRECTED here by Angular. The IdP shows its own login/consent UI.
        idp.MapGet("/authorize", (FakeIdentityProvider p, string client_id, string redirect_uri, string response_type,
                                  string code_challenge, string code_challenge_method, string state, string? scope, string? nonce) =>
        {
            if (response_type != "code" || code_challenge_method != "S256")
                return Results.BadRequest(new { error = "unsupported_response_type", hint = "Only code + PKCE S256" });
            if (!p.IsValidClient(client_id, redirect_uri))
                return Results.BadRequest(new { error = "invalid_client", hint = "client_id or redirect_uri not registered" });

            return Results.Content(ConsentPage(client_id, redirect_uri, code_challenge, state, nonce ?? "", scope ?? "openid"), "text/html");
        });

        // Step 2 — consent form submitted → code issued → redirect back to the SPA with ?code=&state=
        idp.MapPost("/authorize", async (HttpRequest req, FakeIdentityProvider p, InMemoryUserStore users) =>
        {
            var f = await req.ReadFormAsync();
            var redirectUri = f["redirect_uri"].ToString();
            var state = f["state"].ToString();

            if (f["action"] == "deny")
                return Results.Redirect($"{redirectUri}?error=access_denied&state={Uri.EscapeDataString(state)}");

            var user = users.Validate(f["username"].ToString(), f["password"].ToString());
            if (user is null)
                return Results.Content(ConsentPage(f["client_id"]!, redirectUri, f["code_challenge"]!, state, f["nonce"]!, f["scope"]!, "Invalid credentials"), "text/html");

            var code = p.IssueCode(user.UserName, f["code_challenge"]!, redirectUri, f["nonce"]!);
            return Results.Redirect($"{redirectUri}?code={Uri.EscapeDataString(code)}&state={Uri.EscapeDataString(state)}");
        });

        // Step 3 — back-channel: Angular POSTs code + code_verifier (form-encoded, per RFC 6749).
        idp.MapPost("/token", async (HttpRequest req, FakeIdentityProvider p) =>
        {
            var f = await req.ReadFormAsync();
            if (f["grant_type"] != "authorization_code")
                return Results.BadRequest(new { error = "unsupported_grant_type" });

            var (error, tokens) = p.Exchange(f["code"]!, f["code_verifier"]!, f["redirect_uri"]!);
            return error is null ? Results.Ok(tokens) : Results.BadRequest(new { error });
        }).DisableAntiforgery();

        idp.MapGet("/userinfo", (ClaimsPrincipal user, FakeIdentityProvider p) =>
                p.UserInfo(user.Identity!.Name!) is { } info ? Results.Ok(info) : Results.NotFound())
           .RequireAuthorization(a => a.AddAuthenticationSchemes(AuthSchemes.Oidc).RequireAuthenticatedUser());

        // Our API accepting the IdP's token (second JwtBearer scheme).
        app.MapGet("/api/auth/oidc/me", (ClaimsPrincipal user) => TypedResults.Ok(JwtEndpoints.Describe(user)))
           .RequireAuthorization(a => a.AddAuthenticationSchemes(AuthSchemes.Oidc).RequireAuthenticatedUser())
